def apply_api_repair() -> None:
    """Make TypeScript select backend phrases and fail closed when they are absent."""
    replace_once(
        API,
        '''export type CloudCopyApprovalAction = "copy-only" | "adopt-existing-copy";

export interface CloudCopyApproval {
''',
        '''export type CloudCopyApprovalAction = "copy-only" | "adopt-existing-copy";

/** Exact phrases generated by Rust for one immutable review fingerprint. */
export interface CloudCopyApprovalPhraseSet {
  /** Phrase required before a new verified cloud copy may start. */
  copy_only: string;
  /** Phrase required before an existing verified destination may be adopted. */
  adopt_existing_copy: string;
}

export interface CloudCopyApproval {
''',
    )
    replace_once(
        API,
        '''export interface CloudPlanReport {
  cloud_root: CloudRoot;
  generated_at_ms: number;
  candidates: CloudCandidate[];
''',
        '''export interface CloudPlanReport {
  cloud_root: CloudRoot;
  generated_at_ms: number;
  /** Rust-owned approval phrases keyed by the candidate's exact review fingerprint. */
  copy_approval_phrases: Readonly<Record<string, CloudCopyApprovalPhraseSet>>;
  candidates: CloudCandidate[];
''',
    )
    replace_once(
        API,
        '''export const cloudCopyApprovalPhrase = (
  candidate: Pick<CloudCandidate, "review_fingerprint">,
  action: CloudCopyApprovalAction,
) => `DiskSage cloud ${action} ${candidate.review_fingerprint} 승인`;
''',
        '''/** Select an exact Rust-generated approval phrase without reconstructing policy in UI code. */
export function cloudCopyApprovalPhrase(
  candidate: Pick<CloudCandidate, "review_fingerprint">,
  action: CloudCopyApprovalAction,
  phraseSets: Readonly<Record<string, CloudCopyApprovalPhraseSet>>,
): string | null {
  const phrases = phraseSets[candidate.review_fingerprint];
  if (!phrases) return null;
  return action === "copy-only" ? phrases.copy_only : phrases.adopt_existing_copy;
}
''',
    )


