def apply_api_tests() -> None:
    """Cover both action branches and the missing-current-plan failure path."""
    replace_once(
        API_TEST,
        '''describe("cloud copy approval phrase", () => {
  it("binds the exact review fingerprint and requested action", () => {
    const candidate = { review_fingerprint: "a".repeat(64) };
    expect(api.cloudCopyApprovalPhrase(candidate, "copy-only")).toBe(
      `DiskSage cloud copy-only ${"a".repeat(64)} 승인`,
    );
    expect(api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy")).toBe(
      `DiskSage cloud adopt-existing-copy ${"a".repeat(64)} 승인`,
    );
  });
});
''',
        '''describe("cloud copy approval phrase", () => {
  const reviewFingerprint = "a".repeat(64);
  const candidate = { review_fingerprint: reviewFingerprint };
  const phraseSets = {
    [reviewFingerprint]: {
      copy_only: "backend copy-only approval",
      adopt_existing_copy: "backend existing-copy adoption",
    },
  };

  it("selects each backend-returned action phrase for the exact review fingerprint", () => {
    expect(api.cloudCopyApprovalPhrase(candidate, "copy-only", phraseSets)).toBe(
      "backend copy-only approval",
    );
    expect(api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy", phraseSets)).toBe(
      "backend existing-copy adoption",
    );
  });

  it("fails closed when the current plan omitted the exact review fingerprint", () => {
    expect(api.cloudCopyApprovalPhrase(candidate, "copy-only", {})).toBeNull();
    expect(api.cloudCopyApprovalPhrase(candidate, "adopt-existing-copy", {})).toBeNull();
  });
});
''',
    )


def update_changelog() -> None:
    """Record the completed policy-ownership repair once in the unreleased notes."""
    text = CHANGELOG.read_text(encoding="utf-8")
    entry = (
        "- Source cloud copy and existing-copy adoption approval phrases from the Rust "
        "plan response, so the frontend cannot drift from the authorization policy.\n"
    )
    if entry in text:
        return
    marker = "## [Unreleased]\n"
    if text.count(marker) != 1:
        raise SystemExit("CHANGELOG missing one [Unreleased] section")
    CHANGELOG.write_text(text.replace(marker, marker + "\n" + entry, 1), encoding="utf-8")


def apply_repair() -> None:
    """Apply the production repair only after the regression has failed."""
    apply_commands_repair()
    apply_api_repair()
    apply_archive_repair()
    apply_api_tests()
    update_changelog()


def cleanup() -> None:
    """Remove the completed one-shot workflow and helper before publishing."""
    for path in (WORKFLOW, SCRIPT):
        if not path.exists():
            raise SystemExit(f"expected one-shot path to exist: {path}")
    WORKFLOW.unlink()
    SCRIPT.unlink()


def main() -> None:
    """Run one exact-head phase selected by the bounded workflow."""
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=("add-test", "apply", "cleanup"))
    args = parser.parse_args()
    if args.phase == "add-test":
        add_test()
    elif args.phase == "apply":
        apply_repair()
    else:
        cleanup()


if __name__ == "__main__":
    main()
